-- USE FraudDetectionDB;
-- GO
IF OBJECT_ID('TRANSACTIONS', 'U') IS NOT NULL DROP TABLE TRANSACTIONS;
IF OBJECT_ID('ACCOUNTS', 'U') IS NOT NULL DROP TABLE ACCOUNTS;
IF OBJECT_ID('MERCHANTS', 'U') IS NOT NULL DROP TABLE MERCHANTS;
IF OBJECT_ID('CUSTOMERS', 'U') IS NOT NULL DROP TABLE CUSTOMERS;
GO


-- CREATE TABLES

CREATE TABLE CUSTOMERS (
    customer_id     CHAR(9)         PRIMARY KEY,
    full_name       VARCHAR(60)     NOT NULL,
    email           VARCHAR(80)     NOT NULL,
    phone           VARCHAR(15)     NOT NULL,
    date_of_birth   DATE            NOT NULL,
    city            VARCHAR(30)     NOT NULL,
    country         VARCHAR(20)     NOT NULL DEFAULT 'Nigeria',
    account_open_date DATE          NOT NULL,
    credit_score    INT             NOT NULL,
    annual_income   DECIMAL(12,2)   NOT NULL,
    risk_level      VARCHAR(10)     NOT NULL
);
GO

CREATE TABLE ACCOUNTS (
    account_id      CHAR(9)         PRIMARY KEY,
    customer_id     CHAR(9)         NOT NULL REFERENCES CUSTOMERS(customer_id),
    account_type    VARCHAR(15)     NOT NULL,
    account_number  VARCHAR(12)     NOT NULL,
    balance         DECIMAL(15,2)   NOT NULL,
    account_status  VARCHAR(15)     NOT NULL,
    open_date       DATE            NOT NULL,
    credit_limit    DECIMAL(12,2)   NOT NULL
);
GO

CREATE TABLE MERCHANTS (
    merchant_id     CHAR(8)         PRIMARY KEY,
    merchant_name   VARCHAR(50)     NOT NULL,
    category        VARCHAR(20)     NOT NULL,
    city            VARCHAR(30)     NOT NULL,
    country         VARCHAR(20)     NOT NULL,
    risk_level      VARCHAR(10)     NOT NULL
);
GO

CREATE TABLE TRANSACTIONS (
    transaction_id      CHAR(10)        PRIMARY KEY,
    account_id          CHAR(9)         NOT NULL REFERENCES ACCOUNTS(account_id),
    merchant_id         CHAR(8)         NOT NULL REFERENCES MERCHANTS(merchant_id),
    transaction_date    DATETIME        NOT NULL,
    amount              DECIMAL(15,2)   NOT NULL,
    transaction_type    VARCHAR(20)     NOT NULL,
    location_city       VARCHAR(30)     NOT NULL,
    location_country    VARCHAR(20)     NOT NULL,
    device_type         VARCHAR(20)     NOT NULL,
    transaction_status  VARCHAR(10)     NOT NULL,
    is_fraud            BIT             NOT NULL DEFAULT 0,
    fraud_type          VARCHAR(40)     NULL
);
GO

